package com.automation.model.request;
public class CreateUserRequest { private String name,gender,email,status; public CreateUserRequest(){} public CreateUserRequest(String name,String gender,String email,String status){this.name=name;this.gender=gender;this.email=email;this.status=status;} public String getName(){return name;} public void setName(String v){name=v;} public String getGender(){return gender;} public void setGender(String v){gender=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }